<?php $input = static fn (string $name, string $fallback = ''): string => esc((string) ($formData[$name] ?? $fallback), 'attr'); ?>
<div class="damage-form-grid issue-filters"><label>Summary<input name="summary" maxlength="190" required value="<?= $input('summary') ?>"></label>
<label>Intent<select name="intent_code"><?php foreach (\Config\VehicleDamage::WORK_INTENTS as $code => $label): ?><option value="<?= esc($code, 'attr') ?>" <?= ($formData['intent_code'] ?? 'mitigation') === $code ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Work category<select name="category_code"><?php foreach (\Config\VehicleDamage::WORK_CATEGORIES as $code => $label): ?><option value="<?= esc($code, 'attr') ?>" <?= ($formData['category_code'] ?? '') === $code ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Known vendor (optional)<select name="vendor_company_id"><option value="">Use text / unknown vendor</option><?php foreach ($vendors as $vendor): ?><option value="<?= (int) $vendor['id'] ?>" <?= (string) ($formData['vendor_company_id'] ?? '') === (string) $vendor['id'] ? 'selected' : '' ?>><?= esc($vendor['name']) ?></option><?php endforeach; ?></select></label>
<label>Vendor name as recorded (optional)<input name="vendor_snapshot" maxlength="190" value="<?= $input('vendor_snapshot') ?>"></label>
<label>Vendor order reference (optional)<input name="vendor_order_reference" maxlength="120" value="<?= $input('vendor_order_reference') ?>"></label></div>
<fieldset><legend>Canonical conditions addressed</legend><?php foreach ($vehicleDamage['current'] as $index => $condition): $prefix = 'conditions[' . (int) $index . ']'; ?>
<?php $selectedOriginal = isset($aliasPreview) && (int) $aliasPreview['canonical']['id'] === (int) $condition['id'] ? $aliasPreview['original'] : $condition; ?>
<div class="work-scope"><?php if ((int) $selectedOriginal['id'] !== (int) $condition['id']): ?><p>Selected historical original: <?= esc($selectedOriginal['description']) ?>. Work targets the canonical condition below.</p><?php endif; ?><label><input type="checkbox" name="<?= $prefix ?>[canonical_confirmed]" value="1"> I confirm this canonical work target: <?= esc(\Config\VehicleDamage::PANELS[$condition['panel_code'] ?? ''] ?? $condition['zone_code']) ?> · <?= esc($condition['description']) ?></label>
<input type="hidden" name="<?= $prefix ?>[selected_item_id]" value="<?= (int) $selectedOriginal['id'] ?>"><input type="hidden" name="<?= $prefix ?>[canonical_item_id]" value="<?= (int) $condition['id'] ?>"><input type="hidden" name="<?= $prefix ?>[expected_condition_state]" value="<?= esc($fingerprints[$condition['id']], 'attr') ?>">
<label>Scope note (optional)<textarea name="<?= $prefix ?>[note]" maxlength="2000"><?= esc((string) ($formData['conditions'][$index]['note'] ?? '')) ?></textarea></label></div><?php endforeach; ?></fieldset>
<label>Recording mode<select name="recording_mode"><option value="planned">Plan new work</option><option value="historical_mitigation" <?= ($formData['recording_mode'] ?? '') === 'historical_mitigation' ? 'selected' : '' ?>>Record mitigation already performed</option></select></label>
<details class="capital-disclosure" <?= ($formData['recording_mode'] ?? '') === 'historical_mitigation' ? 'open' : '' ?>><summary>Historical mitigation facts</summary><div class="damage-form-grid issue-filters">
<label>Performed at (leave blank if unknown)<input type="datetime-local" name="performed_at" value="<?= $input('performed_at') ?>"></label>
<label>Recording reason<textarea name="recording_reason" maxlength="2000"><?= esc((string) ($formData['recording_reason'] ?? '')) ?></textarea></label>
<label>Completion note<textarea name="completion_note" maxlength="2000"><?= esc((string) ($formData['completion_note'] ?? '')) ?></textarea></label>
<label><input type="checkbox" name="performed_confirmed" value="1"> I confirm this temporary mitigation was performed and damage remained.</label></div><p>Unknown vendor and exact performed time may remain blank. Record why facts are incomplete.</p></details>
